using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class SpatialApply {
 const string Base="Assets/Afrer_Seconds/05.Model/",P=Base+"Props/B5/",E=Base+"Environment/B5/";static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static Dictionary<string,Material> mats=new Dictionary<string,Material>();static Transform group;
 static Vector3 V(JToken v)=>new Vector3((float)v[0],(float)v[1],(float)v[2]);static GameObject Child(string name,Transform parent){var g=new GameObject(name);g.transform.SetParent(parent,false);return g;}
 static void Mat(string key,Color color,float metal,float smooth,string texture=null,bool transparent=false){string path=P+"Materials/SF_"+key+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){var src=AssetDatabase.LoadAssetAtPath<Material>(P+"Materials/RD_"+key+".mat");m=src?new Material(src):new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.name="SF_"+key;m.SetColor("_BaseColor",color);m.SetFloat("_Metallic",metal);m.SetFloat("_Smoothness",smooth);if(texture!=null){var tex=AssetDatabase.LoadAssetAtPath<Texture2D>(P+"Textures/SF_"+texture+".png");m.SetTexture("_BaseMap",tex);if(texture.EndsWith("_Base")){m.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(P+"Textures/SF_"+texture.Replace("_Base","_Normal")+".png"));m.EnableKeyword("_NORMALMAP");m.SetFloat("_BumpScale",.25f);m.SetTexture("_MetallicGlossMap",AssetDatabase.LoadAssetAtPath<Texture2D>(P+"Textures/SF_"+texture.Replace("_Base","_MetalSmooth")+".png"));m.EnableKeyword("_METALLICSPECGLOSSMAP");m.SetFloat("_Smoothness",1);}}
 if(transparent){m.SetFloat("_Surface",1);m.SetFloat("_SrcBlend",(float)BlendMode.SrcAlpha);m.SetFloat("_DstBlend",(float)BlendMode.OneMinusSrcAlpha);m.SetFloat("_ZWrite",0);m.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");m.SetOverrideTag("RenderType","Transparent");m.renderQueue=3000;m.SetFloat("_Cull",0);}if(key=="Label")m.SetFloat("_SpecularHighlights",0);EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);mats[key]=m;}
 static Material Resolve(string name){string key=name.Substring(name.IndexOf('_')+1);if(mats.TryGetValue(key,out var m))return m;foreach(string prefix in new[]{name.StartsWith("SC_")?"SC_":name.StartsWith("SR_")?"SR_":"RD_","RD_","SC_"}){m=AssetDatabase.LoadAssetAtPath<Material>(P+"Materials/"+prefix+key+".mat");if(m)return m;}throw new Exception("Unmapped material "+name);}
 static GameObject Model(string model,Transform parent,bool environment=false){var path=(environment?E:P)+model+".fbx";var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path),parent);g.transform.localPosition=Vector3.zero;g.transform.localRotation=Quaternion.identity;g.transform.localScale=Vector3.one;foreach(var r in g.GetComponentsInChildren<Renderer>())r.sharedMaterials=r.sharedMaterials.Select(m=>Resolve(m.name)).ToArray();return g;}
 static void Collide(GameObject g,string model){bool exact=model.Contains("MedicalBed")||model.Contains("PrivacyCurtain")||model.Contains("ExaminationLight")||model.Contains("DeconShower")||model.Contains("TestGantry")||model.Contains("CompactToilet")||model.Contains("TaskChair")||model.EndsWith("_Interior");if(exact){foreach(var f in g.GetComponentsInChildren<MeshFilter>())f.gameObject.AddComponent<MeshCollider>().sharedMesh=f.sharedMesh;}else{var fs=g.GetComponentsInChildren<MeshFilter>();var b=fs[0].sharedMesh.bounds;foreach(var f in fs.Skip(1))b.Encapsulate(f.sharedMesh.bounds);var c=g.AddComponent<BoxCollider>();c.center=b.center;c.size=b.size;}}
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||!s.path.EndsWith("Level_B5_Circular.unity"))throw new Exception("B5 Edit required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;if(root.Find("B5_Spatial_Refinement"))throw new Exception("Already applied");string backup=Path.Combine(Path.GetTempPath(),"AfterSeconds_SpatialApply_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".unity");if(!EditorSceneManager.SaveScene(s,backup,true))throw new Exception("Backup failed");if(s.isDirty)EditorSceneManager.SaveScene(s);
 foreach(var f in Directory.GetFiles(Path.Combine(Application.dataPath,"Afrer_Seconds/05.Model/Props/B5/Textures"),"SF_*.png")){string path=P+"Textures/"+Path.GetFileName(f);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var t=(TextureImporter)AssetImporter.GetAtPath(path);t.maxTextureSize=path.Contains("EquipmentPrint")?4096:1024;t.textureCompression=TextureImporterCompression.CompressedHQ;t.mipmapEnabled=true;t.filterMode=FilterMode.Trilinear;t.wrapMode=TextureWrapMode.Repeat;if(path.Contains("_Normal"))t.textureType=TextureImporterType.NormalMap;else if(path.Contains("MetalSmooth"))t.sRGBTexture=false;t.SaveAndReimport();}
 Mat("Coat",Color.white,.12f,.4f,"Coat_Base");Mat("Steel",Color.white,.8f,.6f,"Steel_Base");Mat("Floor",Color.white,.02f,.3f,"Floor_Base");Mat("Accent",new Color(.21f,.39f,.43f),.22f,.42f,"Coat_Base");Mat("WarmAccent",new Color(.58f,.49f,.33f),.1f,.4f,"Coat_Base");Mat("Blue",new Color(.18f,.27f,.38f),.22f,.4f,"Coat_Base");Mat("Frost",new Color(.45f,.59f,.61f,.30f),.02f,.5f,null,true);Mat("Window",new Color(.2f,.36f,.40f,.10f),.03f,.8f,null,true);Mat("Gasket",new Color(.016f,.024f,.03f),0,.25f);Mat("Label",Color.white,0,.2f,"EquipmentPrint");Mat("FloorZone",new Color(.27f,.38f,.41f),.02f,.3f,"Floor_Base");
 var manifest=JObject.Parse(File.ReadAllText(Repo+"/SourceAssets/B5_SpatialRefinement/models.json"));foreach(var entry in manifest){string path=((string)entry.Value["category"]=="Props"?P:E)+entry.Key+".fbx";AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var mi=(ModelImporter)AssetImporter.GetAtPath(path);mi.importAnimation=false;mi.importCameras=false;mi.importLights=false;mi.isReadable=true;mi.importNormals=ModelImporterNormals.Import;mi.importTangents=ModelImporterTangents.CalculateMikk;var src=AssetDatabase.LoadAssetAtPath<GameObject>(path);foreach(var m in src.GetComponentsInChildren<Renderer>().SelectMany(r=>r.sharedMaterials).Where(m=>m).Distinct())mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),m.name),Resolve(m.name));mi.SaveAndReimport();}
 var plan=JObject.Parse(File.ReadAllText(Repo+"/SourceAssets/B5_SpatialRefinement/plan.json"));group=Child("B5_Spatial_Refinement",root).transform;group.localPosition=Vector3.zero;foreach(var entry in (JObject)plan["rooms"]){if(entry.Key=="C01")continue;var room=Child(entry.Key,group).transform;room.position=V(entry.Value["position"]);var g=Model("SF_"+entry.Key+"_Interior",room,true);Collide(g,g.name);}
 var archived=new List<string>();var old=root.Find("Remaining_Domes_Art");foreach(var t in old.GetComponentsInChildren<Transform>(true).Where(t=>t.parent!=null&&t.parent.parent==old).ToArray()){var path=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject);if(path.Contains("/Props/")||t.name=="RD_C03_ProcessConnections"){t.gameObject.SetActive(false);archived.Add(t.parent.name+"/"+t.name);}}
 foreach(var p in plan["placements"]){var g=Model((string)p["model"],group.Find((string)p["room"]));g.name=(string)p["id"];g.transform.localPosition=V(p["position"]);g.transform.localRotation=Quaternion.Euler(0,(float)p["yaw"],0);Collide(g,(string)p["model"]);}
 int security=0;foreach(var t in root.Find("C02_Security_Art").Cast<Transform>().ToArray()){string path=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject);if(!path.Contains("/Props/")||!t.gameObject.activeSelf)continue;string model=Path.GetFileNameWithoutExtension(path);string replacement=model=="SC_TaskChair"?"SF_TaskChair":"SF_"+model;if(!manifest.ContainsKey(replacement))continue;var g=Model(replacement,group.Find("C02"));g.name="C02_Detail_"+security++;g.transform.SetPositionAndRotation(t.position,t.rotation);Collide(g,replacement);t.gameObject.SetActive(false);archived.Add("C02/"+t.name);}
 var fixtures=JArray.Parse(File.ReadAllText(Repo+"/SourceAssets/B5_SpatialRefinement/fixtures.json"));int i=0;foreach(var f in fixtures){var g=Child("Fixture_Downlight_"+i++,group.Find((string)f["room"]));g.transform.localPosition=V(f["position"]);g.transform.localRotation=Quaternion.Euler(90,0,0);var l=g.AddComponent<Light>();l.type=LightType.Spot;l.spotAngle=110;l.innerSpotAngle=65;l.range=(float)f["range"];l.intensity=(float)f["intensity"];l.color=new Color(.83f,.93f,1);l.shadows=LightShadows.None;}
 foreach(var t in group.GetComponentsInChildren<Transform>(true))if(PrefabUtility.IsPartOfPrefabInstance(t)){PrefabUtility.RecordPrefabInstancePropertyModifications(t);PrefabUtility.RecordPrefabInstancePropertyModifications(t.gameObject);foreach(var r in t.GetComponents<Renderer>())PrefabUtility.RecordPrefabInstancePropertyModifications(r);}foreach(var t in old.GetComponentsInChildren<Transform>(true))if(PrefabUtility.IsPartOfPrefabInstance(t))PrefabUtility.RecordPrefabInstancePropertyModifications(t.gameObject);foreach(var t in root.Find("C02_Security_Art").GetComponentsInChildren<Transform>(true))if(PrefabUtility.IsPartOfPrefabInstance(t))PrefabUtility.RecordPrefabInstancePropertyModifications(t.gameObject);
 Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);var result=new{scene=s.path,backup,models=manifest.Count,placements=plan["placements"].Count(),security,fixtureLights=i,archived};File.WriteAllText(Repo+"/Docs/검수/2026-11-08_B5_SpatialRefinement/apply.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
